// @ts-check
/*
 * WebMCP page tools.
 *
 * Tools that work on the page the user sees: what the page is, what it shows, where its menus lead, opening another
 * page of the same site, and reading and filling its forms. They never submit a form and never leave the site, so the user always
 * reviews and saves the changes an agent makes.
 *
 * The tools are registered with the standard `document.modelContext.registerTool`, so any WebMCP agent can use them:
 * the browser's own assistant, or the CrestApps AI chat. As WebMCP defines, each answers a JSON-serializable value and
 * reports a failure by rejecting. Load webmcp-polyfill.js first in browsers without native WebMCP.
 */

(function () {
  'use strict';

  var MAX_HEADINGS = 20;
  var MAX_LINKS = 200;
  var MAX_FIELDS = 200;
  var MAX_VALUE_LENGTH = 2000;
  var MAX_CONTENT_LENGTH = 8000;
  var MAX_TABLES = 10;
  var MAX_TABLE_ROWS = 50;
  var MAX_CELL_LENGTH = 300;

  // The selectors the tools read the page with.
  var selectors = {
    description: 'meta[name="description"]',
    headings: 'h1, h2',
    main: 'main, [role="main"]',
    // What page_read_content leaves out of the page's text: scripts, menus, the choices and text of form controls
    // (page_list_form_fields reads them), hidden parts, the chat itself, and anything a page marks with
    // data-webmcp-ignore. A form's other content is read: admin pages often wrap a whole list in one, for bulk actions.
    ignored: 'script, style, noscript, template, svg, nav, aside, select, textarea, datalist, dialog:not([open]), [hidden], [aria-hidden="true"], [role="navigation"], [data-webmcp-ignore], [class*="ai-chat-widget"]',
    links: 'nav a[href], header a[href], aside a[href], [role="navigation"] a[href]',
    fields: 'form input, form select, form textarea',
  };

  // Field types an agent never reads or fills.
  var SKIPPED_TYPES = ['hidden', 'password', 'file', 'submit', 'button', 'reset', 'image'];
  var SKIPPED_NAMES = ['__RequestVerificationToken'];

  function cleanText(value) {
    return (value == null ? '' : String(value)).replace(/\s+/g, ' ').trim();
  }


  // An address that starts with a scheme, such as "https:" or "javascript:".
  var ABSOLUTE_ADDRESS = /^[A-Za-z][A-Za-z0-9+.-]*:/;

  // The tools register() registered, by ModelContext and name, so the CrestApps chat can run them through their own
  // execute and tell the model why one failed (executeTool reports every failure as "Tool execution failed").
  var registeredTools = new WeakMap();

  // Elements that start a new line in the text page_read_content reads.
  var BLOCK_TAGS = ['ADDRESS', 'ARTICLE', 'BLOCKQUOTE', 'BR', 'DD', 'DETAILS', 'DIV', 'DL', 'DT', 'FIELDSET', 'FIGCAPTION', 'FIGURE', 'FOOTER', 'H1', 'H2', 'H3', 'H4', 'H5', 'H6', 'HEADER', 'HR', 'LI', 'OL', 'P', 'PRE', 'SECTION', 'SUMMARY', 'UL'];

  function isIgnored(node) {
    if (node.hidden || (typeof node.matches === 'function' && node.matches(selectors.ignored))) {
      return true;
    }

    // Parts the page hides with CSS, such as closed menus and modals.
    return typeof node.checkVisibility === 'function' && !node.checkVisibility();
  }

  function cellText(cell) {
    var text = cleanText(cell.textContent);

    return text.length > MAX_CELL_LENGTH ? text.slice(0, MAX_CELL_LENGTH) + '…' : text;
  }

  function readTable(table) {
    var rows = Array.prototype.slice.call(table.rows || []);
    var headers = [];

    if (rows.length && Array.prototype.every.call(rows[0].cells || [], function (cell) { return (cell.tagName || '').toUpperCase() === 'TH'; })) {
      headers = Array.prototype.map.call(rows.shift().cells, cellText);
    }

    var caption = table.caption ? cleanText(table.caption.textContent) : '';

    return {
      caption: caption || null,
      headers: headers,
      rows: rows.slice(0, MAX_TABLE_ROWS).map(function (row) {
        return Array.prototype.map.call(row.cells || [], cellText);
      }),
      totalRows: rows.length,
    };
  }

  /**
   * Reads the text and the tables of the page's main region, the way a person reads it: menus, forms, hidden parts
   * and the chat are left out, and each table is read once, as rows, where the text says [table N].
   */
  function readContent(doc) {
    var root = doc.querySelector(selectors.main) || doc.body;
    var lines = [];
    var line = [];
    var tables = [];
    var tableCount = 0;

    function endLine() {
      var text = cleanText(line.join(' '));

      if (text) {
        lines.push(text);
      }

      line = [];
    }

    function walk(node) {
      if (node.nodeType === 3) {
        line.push(node.nodeValue);

        return;
      }

      if (node.nodeType !== 1 || isIgnored(node)) {
        return;
      }

      var tag = (node.tagName || '').toUpperCase();

      if (tag === 'TABLE') {
        endLine();
        tableCount++;

        if (tables.length < MAX_TABLES) {
          tables.push(readTable(node));
          lines.push('[table ' + tables.length + ']');
        }

        return;
      }

      var isBlock = BLOCK_TAGS.indexOf(tag) >= 0;

      if (isBlock) {
        endLine();
      }

      var children = node.childNodes || [];

      for (var i = 0; i < children.length; i++) {
        walk(children[i]);
      }

      if (isBlock) {
        endLine();
      }
    }

    if (root) {
      walk(root);
      endLine();
    }

    var text = lines.join('\n');
    var truncated = text.length > MAX_CONTENT_LENGTH || tableCount > tables.length ||
      tables.some(function (table) { return table.totalRows > table.rows.length; });

    return {
      text: text.length > MAX_CONTENT_LENGTH ? text.slice(0, MAX_CONTENT_LENGTH) + '…' : text,
      tables: tables,
      truncated: truncated,
    };
  }

  function resolveSameOrigin(href, loc) {
    if (!href) {
      return null;
    }

    try {
      var url = new URL(href, loc.href);

      return url.origin === loc.origin ? url : null;
    } catch (error) {
      return null;
    }
  }

  function fieldType(field) {
    var tag = (field.tagName || '').toLowerCase();

    if (tag === 'select' || tag === 'textarea') {
      return tag;
    }

    return (field.type || 'text').toLowerCase();
  }

  function fieldLabel(field) {
    if (field.labels && field.labels.length > 0) {
      var label = cleanText(field.labels[0].textContent);

      if (label) {
        return label;
      }
    }

    return cleanText(field.getAttribute('aria-label')) || cleanText(field.getAttribute('placeholder'));
  }

  function isListed(field) {
    return !field.disabled &&
      SKIPPED_TYPES.indexOf(fieldType(field)) < 0 &&
      SKIPPED_NAMES.indexOf(field.name) < 0;
  }

  function listFields(doc) {
    var fields = [];
    var all = doc.querySelectorAll(selectors.fields);

    for (var i = 0; i < all.length && fields.length < MAX_FIELDS; i++) {
      if (isListed(all[i])) {
        fields.push(all[i]);
      }
    }

    return fields;
  }

  function describeField(field) {
    var type = fieldType(field);
    var description = {
      key: field.name || field.id,
      name: field.name,
      id: field.id,
      label: fieldLabel(field),
      type: type,
      value: type === 'checkbox' || type === 'radio'
        ? !!field.checked
        : String(field.value == null ? '' : field.value).substring(0, MAX_VALUE_LENGTH),
      required: !!field.required,
    };

    if (type === 'select') {
      description.options = Array.prototype.map.call(field.options || [], function (option) {
        return { value: option.value, text: cleanText(option.text), selected: !!option.selected };
      });
    }

    return description;
  }

  function findField(doc, key) {
    var wanted = cleanText(key).toLowerCase();

    if (!wanted) {
      return null;
    }

    var fields = listFields(doc);
    var matchers = [
      function (field) {
        return (field.name || '').toLowerCase() === wanted;
      },
      function (field) {
        return (field.id || '').toLowerCase() === wanted;
      },
      function (field) {
        return fieldLabel(field).toLowerCase() === wanted;
      },
    ];

    for (var m = 0; m < matchers.length; m++) {
      for (var i = 0; i < fields.length; i++) {
        if (matchers[m](fields[i])) {
          return fields[i];
        }
      }
    }

    return null;
  }

  /**
   * Asks the site whether a page exists, with a HEAD request that downloads nothing. Only a 404 or 410 answer means it
   * does not: a page that refuses HEAD (405), sends to the login page or cannot be reached is opened as asked.
   *
   * @param {Function | undefined} fetchImpl The fetch function, or nothing to skip the check.
   * @param {string} href The address.
   */
  async function pageIsMissing(fetchImpl, href) {
    if (typeof fetchImpl !== 'function') {
      return false;
    }

    try {
      var response = await fetchImpl(href, { method: 'HEAD', credentials: 'same-origin', redirect: 'follow' });

      return response.status === 404 || response.status === 410;
    } catch (error) {
      return false;
    }
  }

  function raise(field, type) {
    field.dispatchEvent(new Event(type, { bubbles: true }));
  }

  /**
   * Creates the page tools for a document.
   *
   * @param {{ doc: any, loc: any, isAdmin?: boolean, fetch?: Function, navigateDelayMs?: number }} options The document,
   *   its location, whether it is an admin page, the fetch function page_navigate checks that a page exists with (no
   *   check without it), and how long page_navigate waits after answering before it opens the page.
   */
  function createPageTools(options) {
    var doc = options.doc;
    var loc = options.loc;
    var navigateDelayMs = typeof options.navigateDelayMs === 'number' ? options.navigateDelayMs : 400;

    return [
      {
        name: 'page_get_info',
        title: 'Get page info',
        description: 'Describes the page the user has open: its title, address, description and main headings, and whether it is an admin page. To read what the page shows, use page_read_content.',
        inputSchema: { type: 'object', properties: {} },
        annotations: { readOnlyHint: true },
        execute: function () {
          var meta = doc.querySelector(selectors.description);
          var headings = [];
          var all = doc.querySelectorAll(selectors.headings);

          for (var i = 0; i < all.length && headings.length < MAX_HEADINGS; i++) {
            var text = cleanText(all[i].textContent);

            if (text) {
              headings.push({ level: (all[i].tagName || '').toUpperCase() === 'H1' ? 1 : 2, text: text });
            }
          }

          return ({
            title: doc.title,
            url: loc.href,
            description: meta ? meta.getAttribute('content') : null,
            headings: headings,
            isAdmin: !!options.isAdmin,
          });
        },
      },
      {
        name: 'page_read_content',
        title: 'Read page content',
        description: 'Reads what the page shows in its main area: its text, and its tables as headers and rows (for example the records a list page shows). Menus, forms and hidden parts are left out; use page_list_links and page_list_form_fields for those.',
        inputSchema: { type: 'object', properties: {} },
        annotations: { readOnlyHint: true },
        execute: function () {
          return readContent(doc);
        },
      },
      {
        name: 'page_list_links',
        title: 'List page links',
        description: 'Lists the links in the page\'s menus and navigation that stay on this site, with their text. Use it to find the page to open for a task.',
        inputSchema: {
          type: 'object',
          properties: {
            filter: { type: 'string', description: 'Only list links whose text contains these words.' },
          },
        },
        annotations: { readOnlyHint: true },
        execute: function (input) {
          var filter = cleanText(input && input.filter).toLowerCase();
          var seen = new Set();
          var links = [];
          var all = doc.querySelectorAll(selectors.links);

          for (var i = 0; i < all.length && links.length < MAX_LINKS; i++) {
            var url = resolveSameOrigin(all[i].getAttribute('href'), loc);
            var text = cleanText(all[i].textContent);

            if (!url || !text || seen.has(url.href) || (filter && text.toLowerCase().indexOf(filter) < 0)) {
              continue;
            }

            seen.add(url.href);
            links.push({ text: text, url: url.href });
          }

          return ({ links: links });
        },
      },
      {
        name: 'page_navigate',
        title: 'Open page',
        description: 'Opens another page of this site in the current tab. Only addresses on this site are allowed; take them from page_list_links, and start a site path with /. Unsaved changes on the current page are lost.',
        inputSchema: {
          type: 'object',
          properties: {
            url: { type: 'string', description: 'The address to open: a path that starts with "/", or a full address on this site, as page_list_links lists them.' },
          },
          required: ['url'],
        },
        execute: async function (input) {
          var address = cleanText(input && input.url);

          if (!address) {
            throw new Error('Give the address of the page to open. Call page_list_links to find it.');
          }

          // A bare relative path, such as "ArticlesAdmin", resolves against the current page and usually names a page
          // that does not exist: it is a guess, not an address the site gave.
          if (address.charAt(0) !== '/' && !ABSOLUTE_ADDRESS.test(address)) {
            throw new Error('"' + address + '" is not an address on this site. Give a path that starts with "/" or a full address on this site, as page_list_links lists them. Call page_list_links to find the page to open.');
          }

          var url = resolveSameOrigin(address, loc);

          if (!url) {
            throw new Error('Only addresses on this site can be opened. Call page_list_links to find the page to open.');
          }

          if (await pageIsMissing(options.fetch, url.href)) {
            throw new Error('The site has no page at "' + url.pathname + url.search + '" (404). Do not guess addresses: call page_list_links to find the page to open.');
          }

          // Answer first and open the page a moment later, so the agent gets the result before this page (and
          // the chat connection on it) goes away. The chat finishes the reply on the server and shows it on the
          // next page.
          setTimeout(function () {
            loc.assign(url.href);
          }, navigateDelayMs);

          return ({ navigatedTo: url.href });
        },
      },
      {
        name: 'page_list_form_fields',
        title: 'List form fields',
        description: 'Lists the fields of the forms on the page: name, label, type, current value, whether it is required and, for lists, the choices. Hidden, password and file fields are not listed.',
        inputSchema: { type: 'object', properties: {} },
        annotations: { readOnlyHint: true },
        execute: function () {
          return ({ fields: listFields(doc).map(describeField) });
        },
      },
      {
        name: 'page_set_form_field',
        title: 'Set form field',
        description: 'Puts a value into one form field on the page, found by its name, id or label. It does not save or submit the form: the user reviews the change and saves it.',
        inputSchema: {
          type: 'object',
          properties: {
            field: { type: 'string', description: 'The field\'s name, id or label, as page_list_form_fields lists it.' },
            value: { description: 'The value. For a check box, true or false. For a list, a choice\'s value or text.' },
          },
          required: ['field', 'value'],
        },
        execute: function (input) {
          var field = findField(doc, input && input.field);

          if (!field) {
            throw new Error('No editable field on the page is named "' + cleanText(input && input.field) + '".');
          }

          var type = fieldType(field);
          var value = input.value;

          if (type === 'checkbox' || type === 'radio') {
            field.checked = value === true || String(value).toLowerCase() === 'true';
          } else if (type === 'select') {
            var wanted = cleanText(value).toLowerCase();
            var option = Array.prototype.find.call(field.options || [], function (candidate) {
              return String(candidate.value).toLowerCase() === wanted || cleanText(candidate.text).toLowerCase() === wanted;
            });

            if (!option) {
              throw new Error('The list "' + fieldLabel(field) + '" has no choice "' + cleanText(value) + '".');
            }

            field.value = option.value;
          } else {
            field.value = value == null ? '' : String(value);
          }

          raise(field, 'input');
          raise(field, 'change');

          return ({ field: describeField(field) });
        },
      },
    ];
  }

  /**
   * Registers the page tools with the page's ModelContext.
   *
   * @param {any} modelContext The page's ModelContext (document.modelContext).
   * @param {{ doc: any, loc: any, isAdmin?: boolean, fetch?: Function }} options The document, its location, whether it
   *   is an admin page, and the fetch function page_navigate checks that a page exists with (no check without it).
   * @param {AbortSignal} [signal] Unregisters the tools when aborted.
   */
  function register(modelContext, options, signal) {
    var tools = registeredTools.get(modelContext);

    if (!tools) {
      tools = new Map();
      registeredTools.set(modelContext, tools);
    }

    return Promise.all(createPageTools(options).map(function (tool) {
      return modelContext.registerTool(tool, signal ? { signal: signal } : {}).then(function () {
        if (signal && signal.aborted) {
          return;
        }

        tools.set(tool.name, tool);

        if (signal) {
          signal.addEventListener('abort', function () {
            if (tools.get(tool.name) === tool) {
              tools.delete(tool.name);
            }
          }, { once: true });
        }
      }, function (error) {
        console.warn('The page tool "' + tool.name + '" could not be registered.', error);
      });
    }));
  }

  /**
   * Answers the page tool register() registered with a ModelContext under a name, with its execute callback, or null
   * when it registered none: another script may have registered a tool of that name first.
   *
   * @param {any} modelContext The ModelContext the tool was registered with.
   * @param {string} name The tool's name.
   */
  function getRegisteredTool(modelContext, name) {
    var tools = modelContext ? registeredTools.get(modelContext) : null;

    return (tools && tools.get(name)) || null;
  }

  window.CrestAppsWebMcpPageTools = {
    selectors: selectors,
    createPageTools: createPageTools,
    register: register,
    getRegisteredTool: getRegisteredTool,
  };

  if (window.document && window.document.modelContext) {
    var config = window.crestAppsWebMcp && window.crestAppsWebMcp.config;

    register(window.document.modelContext, {
      doc: window.document,
      loc: window.location,
      fetch: typeof window.fetch === 'function' ? window.fetch.bind(window) : undefined,
      isAdmin: !!(config && config.isAdmin),
    });
  }
})();
